-- 048. Валентина Петровна: тексты под озвучку (проверка voice-checker 25.11): «на дачу» → «на Кок-Тобе»,
-- без «потом», «уже», «звонили», время словами. Меняется только текст; audio_url и условия сохраняются.
begin;
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— В четверг. Утром, по телефону. Он сказал… Он уехал по делам. В Бишкек, я думаю, он туда часто ездил. Мы не волновались. Нет. Никаких звонков не было. — Поправляет платок. — А в воскресенье я послала Виктора на Кок-Тобе. Потому что… ну, мать чувствует. Вот и всё. Мать чувствует."'::json #>> '{}')) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set fixed_questions = jsonb_set(fixed_questions, '{2,a}', to_jsonb('"— Фархад-ака? Он… двадцать лет как родной. Игорь у него начинал, совсем мальчишкой. Каждую пятницу у меня плов ел. Вот на этом стуле. — Пауза. — Позже у них были… разные годы. Не будем об этом. Но он пришёл. Многие не пришли. А он пришёл."'::json #>> '{}')) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set fixed_questions = jsonb_set(fixed_questions, '{3,a}', to_jsonb('"— Потому что мне сказали: внучку больше не увидите. Вы бы пошли? Вы бы пошли, я вас спрашиваю? — Пауза. — Я не собрала. Сорок, а не шестьдесят. Сорок. Вот почему его… Двадцать тысяч. Их у меня не было. — Голос становится ровным, учительским. — И ещё. Они знали про дом на Кок-Тобе. Про четверги. Про Дашу. Кто им это рассказал? Я знаю, кому был нужен этот дом."'::json #>> '{}')) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R08' then jsonb_set(r, '{text}', to_jsonb('"Валентина Петровна смотрит на красные цифры АОН. Потом на свой блокнот.\n— Игорь поставил. Чтобы я знала, откуда звонок. Ну вот. Знаю. — Садится, спинки стула не касается. — В четверг. Около девяти. Из автомата. Шестьдесят тысяч долларов. Пойдёте в милицию — Дашу не увидите. — Пауза. — Мы с Данияром собрали сорок. Больше не было. Не было больше.\nВ субботу, в половине четвёртого, ещё раз. Вот этот номер. Данияр рядом стоял, видел. Он отвёз деньги. Вернулся. И мы сидели. С половины восьмого до половины второго, здесь, у телефона. Ждали. — Нажимает кнопку, цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать»."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R46' then jsonb_set(r, '{text}', to_jsonb('"Валентина Петровна берёт пейджер. Смотрит на АОН. На блокнот, где цифры её почерком.\n— Его пейджер. В арыке, у ворот… Он не уезжал в Бишкек. — Пауза. — Это я придумала. В пятницу утром сказала Виктору по телефону: Игорь в Бишкеке, вы свободны. Он поверил. Он мне всегда верит. — Дальше коротко, как диктант диктует: — Четверг, девять вечера. Автомат. Шестьдесят тысяч, иначе внучка. С Данияром собрали сорок. Суббота, половина четвёртого, вот этот номер. Данияр отвёз деньги, вернулся. С половины восьмого до половины второго был со мной. — Кладёт пейджер. — Скажите Виктору сами. Я не смогу… Я ему в глаза не смогу."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R65' then jsonb_set(r, '{text}', to_jsonb('"Вы говорите: соседка Шмидтов видела Фархада у того дома. В субботу вечером, в четверть седьмого.\nВалентина Петровна встаёт. Подходит к серванту. За стеклом конверт, на нём её карандашом: «От Фархада — на похороны».\n— Двадцать лет. Вот на этом стуле. По пятницам плов. Игорь у него мальчишкой начинал… — Замолкает. — В воскресенье он пришёл. Вечером. Принёс вот это. А рука у него была расцарапана. Свежо так, красно. Я спросила. Собака, говорит, на базаре. — Пауза. — А в прихожей, когда пальто надел, взял меня за локоть. Тихо так: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». И я подумала: ну хоть один… хоть один обо мне думает. — Закрывает дверцу серванта. — Больше не спрашивайте. Я не знаю, что это значит. Не знаю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R66' then jsonb_set(r, '{text}', to_jsonb('"Вы говорите: пальцы Мамаджанова сняты с люка подвала. Того, где держали Игоря.\nВалентина Петровна выходит в прихожую. Встаёт у зеркала, оно ещё завешено простынёй.\n— Вот здесь он стоял. В воскресенье. В пальто, собрался уходить. — Голос ровный, руки сцеплены. — Принёс конверт на похороны. Рука расцарапана, свежая. Я спросила. Собака на базаре, сказал. А здесь, у двери… взял за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала: бережёт. Бережёт он меня. — Поправляет простыню, хотя та висит ровно. — Идите. Мне надо одной побыть."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R84' then jsonb_set(r, '{text}', to_jsonb('"— Оттуда, значит, был звонок. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R109' then jsonb_set(r, '{text}', to_jsonb('"Валентина Петровна читает. На строке «от Сартаковой В. П.» останавливается.\n— Это я. Я ему всегда пишу: «Позвони маме». Он ругается: мама, люди смеются.\n(пауза)\n— Звонка не было. — Голос ровный, учительский. — Он всегда перезванивал. Всегда."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R198' then jsonb_set(r, '{text}', to_jsonb('"— Оттуда был звонок. Из чужого дома. А я не знала, где это."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R233' then jsonb_set(r, '{text}', to_jsonb('"— Зоя Михайловна всё видит. — Тень улыбки. — Да. Данияр был у меня. Мы ждали звонка. Я вам это говорила."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R238' then jsonb_set(r, '{text}', to_jsonb('"— Задушен. — Спина прямая. — Я вам всё рассказала. Найдите его. Вы ведь его нашли."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R240' then jsonb_set(r, '{text}', to_jsonb('"Валентина Петровна дочитывает.\n— Это его голос был в трубке. Мальчишеский. — Пауза. — Двадцать два года."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R304' then jsonb_set(r, '{text}', to_jsonb('"— По четвергам он отдыхал. На Кок-Тобе. Один. — Валентина Петровна поправляет скатерть. — После развода ему нужно было где-то молчать. Я не спрашивала."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R309' then jsonb_set(r, '{text}', to_jsonb('"— Алия ездила на Кок-Тобе? — Валентина Петровна сжимает губы. — За бумагами, конечно. Она всегда знает, когда что забрать.\n(пауза)\n— Простите. Это к делу не относится."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
commit;
select jsonb_array_length(fixed_questions) q, jsonb_array_length(reaction_rules) r from characters where id = '0e8eb7cc-a947-5525-80eb-0978454d919b';
